std::string signing_input = b64url(header_json) + "." + b64url(claims_json);
EVP_MD_CTX* ctx = EVP_MD_CTX_new();
EVP_DigestSignInit(ctx, nullptr, EVP_sha256(), nullptr, pkey);
size_t siglen = 0;
EVP_DigestSign(ctx, nullptr, &siglen, (const unsigned char*)signing_input.data(), signing_input.size());
std::vector<unsigned char> sig(siglen);
EVP_DigestSign(ctx, sig.data(), &siglen, (const unsigned char*)signing_input.data(), signing_input.size());
std::string token = signing_input + "." + b64url(sig.data(), siglen);
EVP_MD_CTX_free(ctx);
